/**
 * Nightwing desktop pet — standalone, dependency-free, and built from the
 * supplied sprite sheet. The runtime atlas is embedded below as a data URI.
 */
(function (global) {
  "use strict";

  const ATLAS = "data:image/png;base64,";
  const FRAME_WIDTH = 180;
  const FRAME_HEIGHT = 128;
  const ATLAS_COLUMNS = 8;
  const ATLAS_ROWS = 6;
  const DISPLAY = 90;
  const STATES = Object.freeze({
    READY: "ready",
    IDLE: "idle",
    ASKING: "asking",
    PETTED: "petted",
    FLYING: "flying",
    DESTROYED: "destroyed",
  });
  const FRAMES = Object.freeze({
    idle: [0, 1, 2, 3],
    blink: [4, 5, 6],
    wink: [7, 8, 9],
    wag: [10, 11, 12, 13],
    hover: [14, 15, 16, 17, 18, 19],
    beg: [20, 21, 22, 23, 24, 25, 26, 27],
    fly: [28, 29, 30, 31, 32, 33, 34, 35],
    petted: [36, 37, 38, 39, 40, 41, 42, 43],
  });

  const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
  const ease = (t) => 1 - Math.pow(1 - t, 3);

  class DesktopPet {
    constructor(options = {}) {
      this.options = {
        size: DISPLAY,
        margin: 20,
        autoAsk: true,
        ...options,
      };
      this._state = STATES.DESTROYED;
      this._subscribers = new Set();
      this._timers = new Set();
      this._animationTimer = null;
      this._behaviorTimer = null;
      this._raf = null;
      this._root = null;
      this._sprite = null;
      this._effects = null;
      this._style = null;
      this._position = { x: 0, y: 0 };
      this._boundPet = (event) => {
        if (event.type === "keydown" && event.key !== "Enter" && event.key !== " ") return;
        event.preventDefault();
        this.pet();
      };
      this._boundResize = () => this._clampToViewport();
      this.reset();
    }

    getState() {
      return this._state;
    }

    onStateChange(callback) {
      if (typeof callback !== "function") throw new TypeError("onStateChange expects a function");
      this._subscribers.add(callback);
      callback(this._state);
      return () => this._subscribers.delete(callback);
    }

    pet() {
      if (this._state === STATES.DESTROYED || this._state === STATES.FLYING) return false;
      this._beginAction(STATES.PETTED);
      this._play(FRAMES.petted, 145, true);
      this._burstHearts(7);
      this._later(() => this._settle(), 1850);
      return true;
    }

    ask() {
      if (this._state === STATES.DESTROYED || this._state === STATES.FLYING || this._state === STATES.ASKING) return false;
      this._beginAction(STATES.ASKING);
      this._root.classList.add("dp-asking");
      this._play(FRAMES.beg, 210, true);
      const heart = document.createElement("span");
      heart.className = "dp-pulse-heart";
      heart.setAttribute("aria-hidden", "true");
      this._effects.appendChild(heart);
      const message = document.createElement("span");
      message.className = "dp-pet-me";
      message.textContent = "Pet me";
      message.setAttribute("aria-hidden", "true");
      this._effects.appendChild(message);
      return true;
    }

    fly() {
      if (this._state === STATES.DESTROYED || this._state === STATES.FLYING || this._state === STATES.ASKING) return false;
      this._beginAction(STATES.FLYING);
      this._play(FRAMES.fly, 125, true);
      const start = { ...this._position };
      const maxX = Math.max(8, window.innerWidth - this.options.size - 8);
      const maxY = Math.max(8, window.innerHeight - this._frameHeight() - 8);
      let target = {
        x: 8 + Math.random() * Math.max(1, maxX - 8),
        y: 8 + Math.random() * Math.max(1, maxY - 8),
      };
      if (Math.hypot(target.x - start.x, target.y - start.y) < 120) {
        target = { x: maxX - start.x > 120 ? maxX : 8, y: maxY * 0.28 };
      }
      const started = performance.now();
      const duration = 1800;
      const step = (now) => {
        if (this._state !== STATES.FLYING || !this._root) return;
        const progress = clamp((now - started) / duration, 0, 1);
        const amount = ease(progress);
        this._position.x = start.x + (target.x - start.x) * amount;
        this._position.y = start.y + (target.y - start.y) * amount - Math.sin(progress * Math.PI) * 52;
        this._place();
        if (progress < 1) this._raf = requestAnimationFrame(step);
        else {
          this._raf = null;
          this._position = target;
          this._place();
          this._settle();
        }
      };
      this._raf = requestAnimationFrame(step);
      return true;
    }

    destroy() {
      if (this._state === STATES.DESTROYED && !this._root) return false;
      this._cancelWork();
      window.removeEventListener("resize", this._boundResize);
      if (this._root) {
        this._root.removeEventListener("pointerdown", this._boundPet);
        this._root.removeEventListener("keydown", this._boundPet);
        this._root.remove();
      }
      if (this._style) this._style.remove();
      this._root = this._sprite = this._effects = this._style = null;
      this._setState(STATES.DESTROYED);
      return true;
    }

    reset() {
      if (this._root || this._state !== STATES.DESTROYED) this.destroy();
      this._installStyles();
      this._build();
      this._position = this._defaultPosition();
      this._place();
      window.addEventListener("resize", this._boundResize, { passive: true });
      this._root.addEventListener("pointerdown", this._boundPet);
      this._root.addEventListener("keydown", this._boundPet);
      this._setFrame(FRAMES.idle[0]);
      this._setState(STATES.READY);
      this._later(() => this._settle(), 750);
      return true;
    }

    _installStyles() {
      document.getElementById("desktop-pet-runtime-styles")?.remove();
      this._style = document.createElement("style");
      this._style.id = "desktop-pet-runtime-styles";
      this._style.textContent = `
        .desktop-pet-root{position:fixed;z-index:2147483000;width:${this.options.size}px;height:${this._frameHeight()}px;cursor:pointer;user-select:none;touch-action:manipulation;outline:none;filter:drop-shadow(0 12px 12px rgba(13,12,18,.18))}
        .desktop-pet-root:focus-visible{border-radius:28px;box-shadow:0 0 0 4px rgba(123,92,246,.28)}
        .desktop-pet-sprite{position:absolute;inset:0;background-image:url('${ATLAS}');background-repeat:no-repeat;background-size:${this.options.size * ATLAS_COLUMNS}px ${this._frameHeight() * ATLAS_ROWS}px;image-rendering:pixelated;image-rendering:crisp-edges;transform-origin:50% 85%}
        .desktop-pet-effects{position:absolute;inset:0;pointer-events:none;overflow:visible}
        .dp-heart,.dp-pulse-heart{display:block;width:2px;height:2px;background:currentColor;color:#ed6485;box-shadow:2px 0 currentColor,6px 0 currentColor,8px 0 currentColor,-2px 2px currentColor,0 2px currentColor,2px 2px currentColor,4px 2px currentColor,6px 2px currentColor,8px 2px currentColor,10px 2px currentColor,-2px 4px currentColor,0 4px currentColor,2px 4px currentColor,4px 4px currentColor,6px 4px currentColor,8px 4px currentColor,10px 4px currentColor,0 6px currentColor,2px 6px currentColor,4px 6px currentColor,6px 6px currentColor,8px 6px currentColor,2px 8px currentColor,4px 8px currentColor,6px 8px currentColor,4px 10px currentColor;image-rendering:pixelated}
        .dp-heart{position:absolute;left:50%;top:32%;animation:dp-float 1.25s steps(10,end) forwards}
        .dp-pulse-heart{position:absolute;right:15px;top:10px;animation:dp-pulse .8s steps(2,end) infinite}
        .dp-pet-me{position:absolute;right:9px;top:-27px;padding:5px 10px 6px;border:2px solid #29262f;border-radius:5px;background:#fff;color:#29262f;box-shadow:3px 3px 0 rgba(41,38,47,.2);font:800 13px/1 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:-.02em;white-space:nowrap}
        .dp-pet-me::after{content:"";position:absolute;right:16px;bottom:-8px;width:8px;height:8px;border-right:2px solid #29262f;border-bottom:2px solid #29262f;background:#fff;transform:rotate(45deg)}
        .dp-asking .desktop-pet-sprite{animation:dp-curious 1.15s ease-in-out infinite}
        @keyframes dp-float{0%{opacity:0;transform:translate(var(--dx),10px) scale(.45)}20%{opacity:1}100%{opacity:0;transform:translate(var(--dx),-78px) scale(1.15) rotate(var(--rot))}}
        @keyframes dp-pulse{50%{transform:scale(1.28);filter:drop-shadow(0 0 5px rgba(238,102,141,.35))}}
        @keyframes dp-curious{50%{transform:translateY(-3px) rotate(1.5deg)}}
        @media (prefers-reduced-motion:reduce){.dp-heart{animation-duration:.7s}.dp-pulse-heart,.dp-asking .desktop-pet-sprite{animation-duration:1.4s}}
      `;
      document.head.appendChild(this._style);
    }

    _build() {
      this._root = document.createElement("div");
      this._root.className = "desktop-pet-root";
      this._root.setAttribute("role", "button");
      this._root.setAttribute("tabindex", "0");
      this._root.setAttribute("aria-label", "Pet Nightwing the dragon");
      this._sprite = document.createElement("div");
      this._sprite.className = "desktop-pet-sprite";
      this._effects = document.createElement("div");
      this._effects.className = "desktop-pet-effects";
      this._root.append(this._sprite, this._effects);
      document.body.appendChild(this._root);
    }

    _beginAction(state) {
      this._cancelWork();
      this._clearEffects();
      this._root.classList.remove("dp-asking");
      this._setState(state);
    }

    _settle() {
      if (!this._root || this._state === STATES.DESTROYED) return;
      this._cancelWork();
      this._clearEffects();
      this._root.classList.remove("dp-asking");
      this._setState(STATES.IDLE);
      this._play(FRAMES.idle, 420, true);
      this._scheduleBehavior();
    }

    _scheduleBehavior() {
      const delay = 4200 + Math.random() * 3200;
      this._behaviorTimer = this._later(() => {
        if (this._state !== STATES.IDLE) return;
        const sequence = Math.random() < 0.58 ? FRAMES.blink : FRAMES.wag;
        this._play(sequence, sequence === FRAMES.wag ? 220 : 150, false, () => {
          if (this._state === STATES.IDLE) {
            this._play(FRAMES.idle, 420, true);
            if (this.options.autoAsk && Math.random() < 0.2) this.ask();
            else this._scheduleBehavior();
          }
        });
      }, delay);
    }

    _play(frames, interval, loop, done) {
      if (this._animationTimer) {
        clearTimeout(this._animationTimer);
        this._timers.delete(this._animationTimer);
      }
      let index = 0;
      const tick = () => {
        if (!this._sprite) return;
        this._setFrame(frames[index]);
        index += 1;
        if (index >= frames.length) {
          if (!loop) {
            this._animationTimer = null;
            done?.();
            return;
          }
          index = 0;
        }
        this._animationTimer = this._later(tick, interval);
      };
      tick();
    }

    _setFrame(frame) {
      const column = frame % ATLAS_COLUMNS;
      const row = Math.floor(frame / ATLAS_COLUMNS);
      this._sprite.style.backgroundPosition = `${-column * this.options.size}px ${-row * this._frameHeight()}px`;
    }

    _burstHearts(count) {
      for (let i = 0; i < count; i += 1) {
        this._later(() => {
          if (!this._effects || this._state !== STATES.PETTED) return;
          const heart = document.createElement("span");
          heart.className = "dp-heart";
          heart.style.setProperty("--dx", `${-56 + Math.random() * 112}px`);
          heart.style.setProperty("--rot", `${-18 + Math.random() * 36}deg`);
          heart.addEventListener("animationend", () => heart.remove(), { once: true });
          this._effects.appendChild(heart);
        }, i * 125);
      }
    }

    _clearEffects() {
      if (this._effects) this._effects.replaceChildren();
    }

    _later(callback, delay) {
      const id = setTimeout(() => {
        this._timers.delete(id);
        callback();
      }, delay);
      this._timers.add(id);
      return id;
    }

    _cancelWork() {
      this._timers.forEach(clearTimeout);
      this._timers.clear();
      this._animationTimer = null;
      this._behaviorTimer = null;
      if (this._raf !== null) cancelAnimationFrame(this._raf);
      this._raf = null;
    }

    _setState(state) {
      if (this._state === state) return;
      this._state = state;
      this._root?.setAttribute("data-state", state);
      this._subscribers.forEach((callback) => {
        try { callback(state); } catch (error) { setTimeout(() => { throw error; }); }
      });
    }

    _defaultPosition() {
      return {
        x: Math.max(8, window.innerWidth - this.options.size - this.options.margin),
        y: Math.max(8, window.innerHeight - this._frameHeight() - this.options.margin),
      };
    }

    _frameHeight() {
      return this.options.size * FRAME_HEIGHT / FRAME_WIDTH;
    }

    _clampToViewport() {
      if (!this._root) return;
      this._position.x = clamp(this._position.x, 8, Math.max(8, window.innerWidth - this.options.size - 8));
      this._position.y = clamp(this._position.y, 8, Math.max(8, window.innerHeight - this._frameHeight() - 8));
      this._place();
    }

    _place() {
      if (!this._root) return;
      this._root.style.left = `${Math.round(this._position.x)}px`;
      this._root.style.top = `${Math.round(this._position.y)}px`;
    }
  }

  DesktopPet.STATES = STATES;
  global.DesktopPet = DesktopPet;

  const script = document.currentScript;
  if (script && script.dataset.autoStart !== "false") {
    const start = () => { if (!global.desktopPet) global.desktopPet = new DesktopPet(); };
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start, { once: true });
    else start();
  }
})(window);
